import { loadFont } from "@remotion/google-fonts/Lexend";
import React, { forwardRef, useEffect, useImperativeHandle, useMemo, useRef, useState, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const lexend = loadFont("normal", {
  weights: ["300"],
  subsets: ["latin"],
});

interface FeatherSettleProps {
  text?: string;
  highlight?: string;
  stagger?: number;
  fall?: number;
  sway?: number;
  /** Peak rock of a falling word, in degrees. */
  tilt?: number;
  accent?: string;
  /** Text color; overrides the theme ink. */
  ink?: string;
  background?: string;
  /** Typeface for the copy. Load it yourself; Lexend by default. */
  fontFamily?: string;
  /** Size of the text block, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: { bg: "#3A2F25", ink: "#EFE6D8", accent: "#9DBF9E" },
  light: { bg: "#EFE6D8", ink: "#3A2F25", accent: "#5E8B60" },
} as const;

const FIRST = 4;
const CYCLES = 1.55;
const TILT = 7;

const DRIFT = Easing.bezier(0.3, 0.05, 0.25, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface Metrics {
  words: number[];
  space: number;
  baseline: number;
}

function measure(words: string[], fontFamily: string): Metrics {
  const ctx = document.createElement("canvas").getContext("2d");
  if (!ctx) {
    return {
      words: words.map((w) => w.length * 0.55),
      space: 0.26,
      baseline: 0.8,
    };
  }
  ctx.font = `300 100px "${fontFamily}"`;
  const fm = ctx.measureText("H");
  const asc = fm.fontBoundingBoxAscent / 100;
  const desc = fm.fontBoundingBoxDescent / 100;
  return {
    words: words.map((w) => ctx.measureText(w).width / 100),
    space: ctx.measureText(" ").width / 100,
    baseline: (1 - (asc + desc)) / 2 + asc,
  };
}

function useMetrics(words: string[], fontFamily: string) {
  const key = `${fontFamily}\u0002${words.join("\u0001")}`;
  const [state, setState] = useState<{ key: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("feather-settle: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      lexend.waitUntilDone(),
      document.fonts.load(`300 100px "${fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({
          key,
          m: measure(key.split("\u0002")[1].split("\u0001"), fontFamily),
        });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle, fontFamily]);
  return state && state.key === key ? state.m : null;
}

function hash(n: number) {
  const s = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return s - Math.floor(s);
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function FeatherSettleBase({
  text = "Your launch, landing softly.",
  highlight = "softly",
  stagger = 13,
  fall = 68,
  sway = 1,
  tilt: tiltMax = TILT,
  accent,
  ink,
  background,
  fontFamily = lexend.fontFamily,
  scale = 1,
  delay = 0,
  speed = 1,
  theme = "dark",
}: FeatherSettleProps) {
  const t = Math.max(0, useCurrentFrame() - delay) * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const spot = accent ?? c.accent;
  const fg = ink ?? c.ink;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);
  const words = useMemo(() => text.split(/\s+/).filter(Boolean), [text]);
  const m = useMetrics(words, fontFamily);

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const portrait = H > W * 1.1;
  const margin = portrait ? W * 0.08 : W * 0.1;
  const room = W - margin * 2;
  const lineEm =
    m.words.reduce((a, w) => a + w, 0) +
    m.space * Math.max(0, words.length - 1);
  const F = Math.min(
    room / Math.max(0.5, lineEm),
    H * (portrait ? 0.06 : 0.12),
  );
  const lineW = lineEm * F;
  const baseY = H * (portrait ? 0.78 : 0.82);
  const x0 = (W - lineW) / 2;
  const hl = highlight
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]/g, "");

  let x = x0;
  const placed = words.map((w, i) => {
    const left = x;
    x += m.words[i] * F + m.space * F;
    return { w, left, width: m.words[i] * F };
  });

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <ScaleLayer scale={scale}>
        {placed.map((p, i) => {
          const start = FIRST + i * stagger;
          const k = interpolate(t, [start, start + fall], [0, 1], CLAMP);
          const drop = DRIFT(k);
          const height = H * (portrait ? 0.5 : 0.6) * (0.9 + hash(i) * 0.2);
          const y = -height * (1 - drop);
          const amp = F * 0.85 * sway * (1 - k) ** 1.6;
          const phase = hash(i + 7) * Math.PI * 2;
          const dir = i % 2 === 0 ? 1 : -1;
          const angle = Math.PI * 2 * CYCLES * k + phase;
          const dx = dir * amp * Math.sin(angle);
          const tilt = dir * tiltMax * sway * (1 - k) ** 1.6 * Math.cos(angle);
          const seen = interpolate(k, [0, 0.22], [0, 1], {
            ...CLAMP,
            easing: EASE_OUT,
          });
          const lit =
            hl.length > 0 && p.w.toLowerCase().replace(/[^a-z0-9]/g, "") === hl;
          return (
            <div
              key={i}
              style={{
                position: "absolute",
                left: p.left,
                top: baseY - m.baseline * F,
                width: p.width,
                height: F,
                lineHeight: `${F}px`,
                fontFamily,
                fontWeight: 300,
                fontSize: F,
                letterSpacing: "-0.01em",
                whiteSpace: "pre",
                color: lit ? spot : fg,
                opacity: seen,
                transformOrigin: "50% 0%",
                transform: `translate(${dx.toFixed(2)}px, ${y.toFixed(2)}px) rotate(${tilt.toFixed(3)}deg)`,
              }}
            >
              {p.w}
            </div>
          );
        })}
      </ScaleLayer>
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  text: {
    type: "text-content",
    default: "Your launch, landing softly.",
    description: "Text",
  },
  highlight: {
    type: "text-content",
    default: "softly",
    description: "Highlight",
  },
  stagger: {
    type: "number",
    default: 13,
    min: 0,
    max: 39,
    step: 1,
    description: "Stagger",
    hiddenFromList: false,
  },
  fall: {
    type: "number",
    default: 68,
    min: 0,
    max: 204,
    step: 1,
    description: "Fall",
    hiddenFromList: false,
  },
  sway: {
    type: "number",
    default: 1,
    min: 0,
    max: 10,
    step: 1,
    description: "Sway",
    hiddenFromList: false,
  },
  tilt: {
    type: "number",
    default: 7,
    min: 0,
    max: 30,
    step: 1,
    description: "Tilt",
    hiddenFromList: false,
  },
  accent: {
    type: "color",
    default: undefined,
    description: "Accent",
  },
  fontFamily: {
    type: "font-family",
    default: "Lexend",
    description: "Font",
  },
  ink: {
    type: "color",
    default: undefined,
    description: "Text color",
  },
  background: {
    type: "color",
    default: undefined,
    description: "Background",
  },
  scale: {
    type: "number",
    default: 1,
    min: 0.5,
    max: 1.5,
    step: 0.05,
    description: "Scale",
    hiddenFromList: false,
  },
  delay: {
    type: "number",
    default: 0,
    min: 0,
    max: 60,
    step: 1,
    description: "Delay (frames)",
    hiddenFromList: false,
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","text","highlight","stagger","fall","sway","tilt","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  text: "Your launch, landing softly.",
  highlight: "softly",
  stagger: 13,
  fall: 68,
  sway: 1,
  tilt: 7,
  fontFamily: "Lexend",
  scale: 1,
  delay: 0,
  speed: 1,
};

type FeatherSettleElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof FeatherSettleBase>;

const FeatherSettleInner = forwardRef<
  HTMLDivElement,
  FeatherSettleElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<FeatherSettle>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <FeatherSettleBase
          {...(componentProps as unknown as ComponentProps<typeof FeatherSettleBase>)}
        />
      </div>
    </Sequence>
  );
});

export const FeatherSettle = Interactive.withSchema({
  Component: FeatherSettleInner,
  componentName: "<FeatherSettle>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
